node -e "
const fs = require('fs');
const p = 'specs/hal-engine-tool-input-validation/spec.md';
let s = fs.readFileSync(p, 'utf8');
const fixes = [
  ['registry.test.ts#L11)', 'registry.test.ts#L13)'],
  ['registry.test.ts#L37)', 'registry.test.ts#L39)'],
  ['registry.test.ts#L61)', 'registry.test.ts#L63)'],
  ['registry.test.ts#L83)', 'registry.test.ts#L85)'],
  ['registry.test.ts#L89)', 'registry.test.ts#L91)'],
  ['registry.test.ts#L113)', 'registry.test.ts#L115)'],
];
for (const [from, to] of fixes) {
  if (!s.includes(from)) { console.error('MISSING', from); process.exit(1); }
  s = s.replace(from, to);
}
fs.writeFileSync(p, s);
console.log('anchors updated');
" && npm run spec:names 2>&1 | tail -2 && npm run check:spec-links 2>&1 | tail -2 && npm run check:spec-status 2>&1 | tail -2
